package com.fitconnect.notification.domain; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity public class Notification {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long userId; private String email; @Enumerated(EnumType.STRING) private NotificationType type; private String subject; @Column(length=4000) private String content; private LocalDateTime sentDate; @Enumerated(EnumType.STRING) private NotificationStatus status; protected Notification(){} public Notification(Long userId,String email,NotificationType type,String subject,String content){this.userId=userId;this.email=email;this.type=type;this.subject=subject;this.content=content;this.status=NotificationStatus.PENDING;} public Long getId(){return id;} public Long getUserId(){return userId;} public String getEmail(){return email;} public NotificationType getType(){return type;} public String getSubject(){return subject;} public String getContent(){return content;} public LocalDateTime getSentDate(){return sentDate;} public NotificationStatus getStatus(){return status;} public void send(){status=NotificationStatus.SENT;sentDate=LocalDateTime.now();} public void fail(){status=NotificationStatus.FAILED;}}
